#pragma once
#include "exotic/runtime/service.hpp"
#include <vector>
namespace exotic::runtime::test {class Service final:public RuntimeService{public:Service(std::string n,std::vector<std::string>d,std::vector<std::string>&events,bool fail=false):n_(std::move(n)),d_(std::move(d)),events_(events),fail_(fail){}std::string name()const override{return n_;}std::vector<std::string>dependencies()const override{return d_;}void recover()override{events_.push_back("recover:"+n_);}void start()override{events_.push_back("start:"+n_);if(fail_)throw ServiceError("injected start failure");running_=true;}void request_stop()override{events_.push_back("stop:"+n_);}void join()override{events_.push_back("join:"+n_);running_=false;}ServiceHealth health()override{return{n_,running_?ServiceState::Running:ServiceState::Stopped,running_?HealthLevel::Healthy:HealthLevel::Unknown,"test",{},Clock::now()};}private:std::string n_;std::vector<std::string>d_;std::vector<std::string>&events_;bool fail_;bool running_{false};};}
